return $input.all().map(it => {
  const j = it.json;
  const g = j.guid;
  const guid = (g && typeof g === 'object') ? (g['#text'] || g._ || j.link) : (g || j.link);
  return { json: {
    title: j.title || '',
    link: j.link || '',
    guid: guid,
    posted_raw: j.pubDate || '',
    description: j.description || '',
    source: 'AusTender',
    search_blob: ((j.title || '') + ' ' + (j.description || '')).toLowerCase()
  }};
});

const meta = $('Normalize (AusTender)').item.json;
return { json: {
  title: meta.title,
  link: meta.link,
  guid: meta.guid,
  source: meta.source,
  posted_raw: meta.posted_raw,
  text: ($json.text || '').toString().slice(0, 4000)
} };

return $input.all().map(it => {
  const j = it.json;
  const rawDesc = (typeof j.description === 'string' ? j.description : JSON.stringify(j.description || '')).toString();
  const cleanDesc = rawDesc
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim();
  const title = (j.title || '').toString();
  const g = j.guid;
  const guid = (g && typeof g === 'object') ? (g['#text'] || g._ || j.link) : (g || j.link);
  return { json: {
    title: title,
    link: j.link || '',
    guid: guid,
    posted_raw: j.pubDate || '',
    source: 'VendorPanel',
    text: (title + ' \u2014 ' + cleanDesc),
    search_blob: (title + ' ' + cleanDesc).toLowerCase()
  }};
});

const BASE = 'https://www.brisbane.qld.gov.au';
const LANDING = BASE + '/business/council-tenders-and-market-led-proposals/current-tenders';
return $input.all().map(it => {
  const html = (it.json.rows || '').toString();
  // first anchor in the row = the tender's own link + name
  const a = html.match(/<a[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/i);
  let link = LANDING, title = '';
  if (a) {
    link = /^https?:/i.test(a[1]) ? a[1] : BASE + (a[1].startsWith('/') ? '' : '/') + a[1];
    title = a[2].replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/\s+/g, ' ').trim();
  }
  const rowText = html.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/\s+/g, ' ').trim();
  if (!title) title = rowText.slice(0, 140);
  return { json: {
    title: title,
    link: link,
    guid: 'BCC:' + (a ? link : rowText.slice(0, 90)),
    posted_raw: '',
    source: 'Brisbane City Council',
    text: rowText,
    search_blob: rowText.toLowerCase()
  }};
}).filter(x =>
  x.json.text.length > 15 &&
  !/^(tender|title|description|closing|status|reference|number)\b/i.test(x.json.title.trim())
);

return $input.all().map(it => {
  const j = it.json;
  const rawDesc = (typeof j.description === 'string' ? j.description : JSON.stringify(j.description || '')).toString();
  const cleanDesc = rawDesc.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/\s+/g, ' ').trim();
  const title = (j.title || '').toString();
  const g = j.guid;
  const guid = (g && typeof g === 'object') ? (g['#text'] || g._ || j.link) : (g || j.link);
  return { json: {
    title: title,
    link: j.link || '',
    guid: guid,
    posted_raw: j.pubDate || '',
    source: 'Extra RSS',
    text: (title + ' \u2014 ' + cleanDesc),
    search_blob: (title + ' ' + cleanDesc).toLowerCase()
  }};
});

const KW = ['security','cleaning','guard','patrol','janitor','facilit','concierge','cctv'];
const out = [];
for (const row of $input.all()) {
  const site = (row.json.SiteName || 'Watchlist').toString();
  const url = (row.json.URL || '').toString().trim();
  if (!url) continue;
  let html = '';
  try {
    const res = await this.helpers.httpRequest({ url, headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36' }, timeout: 20000 });
    html = (typeof res === 'string') ? res : JSON.stringify(res);
  } catch (e) { continue; }
  const originMatch = url.match(/^https?:\/\/[^/]+/);
  const origin = originMatch ? originMatch[0] : '';
  const re = /<a[^>]*href=["']([^"'#]+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let m; const seen = new Set();
  while ((m = re.exec(html)) !== null) {
    let link = m[1];
    const title = m[2].replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/\s+/g, ' ').trim();
    if (title.length < 15) continue;
    const blob = title.toLowerCase();
    if (!KW.some(k => blob.includes(k))) continue;
    if (link.startsWith('/')) link = origin + link;
    if (!/^https?:/i.test(link)) continue;
    if (seen.has(link)) continue; seen.add(link);
    out.push({ json: {
      title: title,
      link: link,
      guid: 'WL:' + link,
      posted_raw: '',
      source: site,
      text: title,
      search_blob: blob
    }});
  }
}
return out;

const store = $getWorkflowStaticData('global');
store.seen = store.seen || [];
const out = [];
for (const item of $input.all()) {
  const id = item.json.guid || item.json.link;
  if (!store.seen.includes(id)) { store.seen.push(id); out.push(item); }
}
if (store.seen.length > 8000) store.seen = store.seen.slice(-8000);
return out;

