const norm = s => (s || '').toString().toLowerCase();
const INTERSTATE = ['nsw','vic','sa','wa','tas','nt','act','new south wales','victoria','tasmania'];

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!['A','B','C'].includes(j.tier)) continue;

  const region = norm(j.region);
  const state  = norm(j.state);
  const loc    = norm(j.location_text);

  // hard reject anything interstate
  if (region === 'interstate' || INTERSTATE.includes(state)) continue;

  let inzone = '';

  // 1) statewide panels are serviceable from SEQ (toggle above)
  if (KEEP_STATEWIDE && region === 'qld-statewide') inzone = 'Statewide';

  // 2) postcode match on the primary location text
  if (!inzone) {
    const found = (loc.match(/\b4\d{3}\b/g) || []);
    if (found.some(pc => POSTCODES.has(pc))) inzone = 'Yes (postcode)';
  }

  // 3) suburb / SEQ-city name match (word-boundary) on the primary location text
  if (!inzone) {
    for (const sub of SUBURBS) {
      if (sub.length < 4) continue;
      const re = new RegExp('(^|[^a-z])' + sub.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '([^a-z]|$)');
      if (re.test(loc)) { inzone = 'Yes (suburb)'; break; }
    }
  }

  if (!inzone) continue;                 // not in the 50km list -> drop
  if (inzone.startsWith('Yes')) j.region = 'SEQ';   // normalise for the sheet
  j.InZone = inzone;
  out.push({ json: j });
}
return out;

